(function(){function Chart(canvas,config){if(!canvas)return;var ctx=canvas.getContext('2d'),w=canvas.clientWidth||canvas.width||600,h=canvas.height||220;canvas.width=w;canvas.height=h;ctx.clearRect(0,0,w,h);var data=(config.data&&config.data.datasets&&config.data.datasets[0]&&config.data.datasets[0].data)||[];var labels=(config.data&&config.data.labels)||[];var max=Math.max.apply(null,data.concat([1]));var pad=34;ctx.font='12px Arial';ctx.strokeStyle='#cbd5e1';ctx.fillStyle='#64748b';ctx.beginPath();ctx.moveTo(pad,10);ctx.lineTo(pad,h-pad);ctx.lineTo(w-10,h-pad);ctx.stroke();if(config.type==='line'){ctx.strokeStyle='#2563eb';ctx.lineWidth=3;ctx.beginPath();data.forEach(function(v,i){var x=pad+(w-pad-20)*(i/(Math.max(data.length-1,1)));var y=h-pad-(h-pad-20)*(v/max);if(i===0)ctx.moveTo(x,y);else ctx.lineTo(x,y);});ctx.stroke();ctx.fillStyle='#2563eb';data.forEach(function(v,i){var x=pad+(w-pad-20)*(i/(Math.max(data.length-1,1)));var y=h-pad-(h-pad-20)*(v/max);ctx.beginPath();ctx.arc(x,y,4,0,Math.PI*2);ctx.fill();});}else{var bw=(w-pad-25)/Math.max(data.length,1)*0.62;data.forEach(function(v,i){var x=pad+12+i*((w-pad-25)/Math.max(data.length,1));var bh=(h-pad-25)*(v/max);ctx.fillStyle='#2563eb';ctx.fillRect(x,h-pad-bh,bw,bh);});}ctx.fillStyle='#475569';labels.forEach(function(label,i){if(i%Math.ceil(labels.length/6||1)===0){var x=pad+(w-pad-20)*(i/(Math.max(labels.length-1,1)));ctx.fillText(String(label).slice(0,12),x-10,h-10);}});return this;}window.Chart=Chart;})();
